-- ============================================================
-- Library Analytics: Book Borrowing Trends and Student Reading Behavior
-- BED 106 - Business Analytics | Checkpoint 1: Data Fundamentals & SQL Querying
-- Database Setup Script (MySQL / phpMyAdmin compatible)
-- Source data: Academic Digital Library Book Recommendation Dataset (Kaggle)
-- NOTE: this is a synthetic/simulated dataset (see Data Source Report, Task 1.2)
-- ============================================================

DROP DATABASE IF EXISTS library_analytics_db;
CREATE DATABASE library_analytics_db;
USE library_analytics_db;

-- ------------------------------------------------------------
-- TABLE 1: users
-- Dimension table: one row per library patron
-- ------------------------------------------------------------
CREATE TABLE users (
    user_id     VARCHAR(15) PRIMARY KEY,
    user_type   VARCHAR(20) NOT NULL,
    department  VARCHAR(30) NOT NULL
);

-- ------------------------------------------------------------
-- TABLE 2: books
-- Dimension table: one row per book/catalog item
-- ------------------------------------------------------------
CREATE TABLE books (
    book_id         VARCHAR(15) PRIMARY KEY,
    book_category   VARCHAR(30) NOT NULL,
    book_format     VARCHAR(20) NOT NULL
);

-- ------------------------------------------------------------
-- TABLE 3: borrowing_events
-- Fact table: one row per user-book interaction event
-- ------------------------------------------------------------
CREATE TABLE borrowing_events (
    event_id                       INT PRIMARY KEY AUTO_INCREMENT,
    user_id                        VARCHAR(15) NOT NULL,
    book_id                        VARCHAR(15) NOT NULL,
    interaction_type               VARCHAR(20) NOT NULL,
    access_mode                    VARCHAR(20) NOT NULL,
    semester_period                VARCHAR(20) NOT NULL,
    borrowing_frequency             INT NOT NULL,
    reading_duration_minutes        DECIMAL(6,2) NOT NULL,
    books_borrowed_last_6_months    INT NOT NULL,
    books_returned_on_time          INT NOT NULL,
    search_count                    INT NOT NULL,
    book_view_count                 INT NOT NULL,
    reservation_count               INT NOT NULL,
    renewal_count                   INT NOT NULL,
    user_rating                     DECIMAL(3,2) NOT NULL,
    book_popularity_score           DECIMAL(4,3) NOT NULL,
    metadata_match_score            DECIMAL(4,3) NOT NULL,
    reading_interest_score          DECIMAL(4,3) NOT NULL,
    user_book_similarity_score      DECIMAL(4,3) NOT NULL,
    feedback_score                  DECIMAL(4,3) NOT NULL,
    feedback_level                  VARCHAR(10) NOT NULL COMMENT 'Low, Medium, or High',
    cold_start_user                 TINYINT(1) NOT NULL COMMENT '1 = new/low-history user, 0 = established user',
    irregular_borrowing_flag        TINYINT(1) NOT NULL COMMENT '1 = irregular borrowing pattern flagged, 0 = normal',
    recommendation_score            DECIMAL(5,3) NOT NULL,
    recommendation_level            VARCHAR(25) NOT NULL COMMENT 'Low_Recommendation, Medium_Recommendation, High_Recommendation',
    CONSTRAINT fk_event_user FOREIGN KEY (user_id) REFERENCES users(user_id),
    CONSTRAINT fk_event_book FOREIGN KEY (book_id) REFERENCES books(book_id)
);

-- ============================================================
-- DATA: users (12000 rows, one per unique patron in the source file)
-- ============================================================

-- ============================================================
-- DATA: books (12000 rows, one per unique catalog item in the source file)
-- ============================================================

